def run(self) -> TMeasurement:
    timer = None
    if self.use_cuda_graph:  # noqa SIM108
        timer = self.run_cudagrah()
    else:
        timer = self.run_eager()
    if not timer.meets_confidence() or timer.has_warnings:
        print("Doesn't meet confidence - re-running bench ...")
        return self.run()
    return timer

def __enter__(self):
    return self

